from rdkit import Chem
from rdkit.Chem import rdDistGeom
smilesK = "CC(=Nc1c(C)cccc1C)[N-][C@H](C2=CC=CC=[N+]2[Ir])C(O)(c3ccccc3)C(F)(F)F"
m = Chem.AddHs(Chem.MolFromSmiles(smilesK))
Na=Np=Ir=None
for a in m.GetAtoms():
    s=a.GetSymbol()
    if s=='Ir': Ir=a.GetIdx()
    elif s=='N':
        if a.GetFormalCharge()==-1: Na=a.GetIdx()
        elif a.GetFormalCharge()==1: Np=a.GetIdx()
nAt=m.GetNumAtoms()
def test(mods):
    mm = Chem.Mol(m)
    b = rdDistGeom.GetMoleculeBoundsMatrix(mm)
    for (i,j,lo,hi) in mods:
        a_,b_=min(i,j),max(i,j); b[a_,b_]=hi; b[b_,a_]=lo
    ps = rdDistGeom.ETKDGv3(); ps.randomSeed=11; ps.SetBoundsMat(b)
    return rdDistGeom.EmbedMolecule(mm, ps)

pairs = [i for i in range(nAt) if i not in (Ir, Na, Np)]
def ok_with(idxs):
    mods = [(Ir,Na,2.05,2.25),(Ir,Np,2.05,2.25)] + [(Ir,i,2.45,30.0) for i in idxs]
    return test(mods) == 0

# bisect
def find_conflict_subset(idxs):
    # returns a minimal-ish conflicting subset
    if len(idxs) <= 2:
        return idxs
    mid = len(idxs)//2
    left, right = idxs[:mid], idxs[mid:]
    if not ok_with(left):
        return find_conflict_subset(left)
    if not ok_with(right):
        return find_conflict_subset(right)
    return idxs  # conflict needs both halves

print('all pairs ok?', ok_with(pairs))
c = find_conflict_subset(pairs)
print('conflicting subset size:', len(c), c[:20])
# check first half / second half
mid = len(pairs)//2
print('left ok?', ok_with(pairs[:mid]), 'right ok?', ok_with(pairs[mid:]))
